{
    "login" : {
        "loginBtn" : "Login",
        "logoutBtn" : "Logout",
        "disclaimerone" : "By logging into SPOTlight, service provider acknowledges and accepts the terms and conditions of use set forth on",
        "disclaimertwo" : "and incorporated by reference in the applicable Independent Service Provider Agreement and/or Transportation Service Provider Agreement."
    },
    "header" : {
        "csa" : "Return to CSA Selection"
    },
    "otpPreference": {
        "title" : "To verify your identity, a one-time passcode will be sent via text message or email to the phone number or email address selected below.",
        "verificationBtn" : "Send Passcode",
        "subTitle" : "Select the phone number or email address (as listed in your MGBA SP Profile):"
    },
    "otpVerify" :{
        "buttonText" : "Verify",
        "resendText" : "RESEND PASSCODE",
        "timerText" : "Try again in",
        "placeHolder" : "Enter Passcode"
    },
    "accessDenied" : {
        "preferenceHeading" : "ACCESS DENIED",
        "preferenceContent" : "Page will be redirected in 10 seconds.",
        "resendHeading" : "PASSCODE TIMEOUT",
        "resendContent" : "Please try again after 1 hour."
    },
    "contract" :{
        "title" : "Welcome",
        "subTitle" : "Please select a Contracted Service Area (CSA) to view.",
        "search" : "Search",
        "open" : "Open",
        "noResult" : "No Results",
        "noContracts" : "No contracted service area(s) available"
    },
    "passcode" : {
        "error" : "Numeric characters only"
    },
    "error" : {
        "header" : "Error",
        "content" : "Please refresh and try again. If the error persists, please contact Help Desk.",
        "okButton" : "OK"
    }
}

